BITS = 14

class TrieNode:
    def __init__(self):
        self.children = [None, None]
        self.count = 0

def count_at_most(nums, limit):
    if limit < 0:
        return 0
    root = TrieNode()
    total = 0
    for num in nums:
        node = root
        b = BITS
        while b >= 0 and node:
            num_bit = (num >> b) & 1
            lim_bit = (limit >> b) & 1
            if lim_bit == 1:
                same_child = node.children[num_bit]
                if same_child:
                    total += same_child.count                     # whole subtree satisfies the bound
                node = node.children[1 - num_bit]                  # continue matching limit exactly
            else:
                node = node.children[num_bit]                        # must match exactly, no addition yet
            b -= 1
        if node:
            total += node.count                                     # exact equality case
        node2 = root
        for b in range(BITS, -1, -1):                              # insert num into the trie
            bit = (num >> b) & 1
            if node2.children[bit] is None:
                node2.children[bit] = TrieNode()
            node2 = node2.children[bit]
            node2.count += 1
    return total

def count_pairs(nums, low, high):
    return count_at_most(nums, high) - count_at_most(nums, low - 1)

