#include <bits/stdc++.h>
using namespace std;
const int BITS = 14;

struct TrieNode { TrieNode* children[2] = {nullptr, nullptr}; int count = 0; };

int countAtMost(vector<int>& nums, int limit) {
    if (limit < 0) return 0;
    TrieNode* root = new TrieNode();
    int total = 0;
    for (int num : nums) {
        TrieNode* node = root;
        for (int b = BITS; b >= 0 && node; b--) {
            int numBit = (num >> b) & 1;
            int limBit = (limit >> b) & 1;
            if (limBit == 1) {
                TrieNode* sameChild = node->children[numBit];
                if (sameChild) total += sameChild->count;                 // whole subtree satisfies the bound
                node = node->children[1 - numBit];                          // continue matching limit exactly
            } else {
                node = node->children[numBit];                                 // must match exactly
            }
        }
        if (node) total += node->count;                                  // exact equality case
        TrieNode* node2 = root;
        for (int b = BITS; b >= 0; b--) {                               // insert num into the trie
            int bit = (num >> b) & 1;
            if (!node2->children[bit]) node2->children[bit] = new TrieNode();
            node2 = node2->children[bit];
            node2->count++;
        }
    }
    return total;
}

int countPairs(vector<int>& nums, int low, int high) {
    return countAtMost(nums, high) - countAtMost(nums, low - 1);
}
